FIXTURES = []
def fixture(fid, sport, comp, a, b, start, official, facts, *, label="", extra=(), missing=(), flags=(), scope="OLBG-listed", sides=(), market_note=""):
    FIXTURES.append({
        "id": fid, "sport": sport, "competition": comp, "a": a, "b": b,
        "start_utc": start, "start_label": label, "source": official,
        "extra_sources": list(extra), "facts": facts, "missing_fields": list(missing),
        "flag_ids": list(flags), "scope": scope, "side_evidence": {"a": sides[0], "b": sides[1]} if sides else {},
        "market_note": market_note,
    })

