PICKS = []
def pick(fid, market, selection, prob, prediction, alternatives=()):
    PICKS.append({"id": f"p-{fid}", "fixture": fid, "market": market, "selection": selection,
                  "prob": prob, "prediction": prediction.strip(), "alternatives": list(alternatives)})
def alt(market, selection, prob):
    return {"market": market, "selection": selection, "prob": prob}

